                bars.append(cl)
    bars.sort(key=len,reverse=True)
    bcolor=bars[0][0][0]
    b1=set(bars[0]); b2=set(bars[1])
    tbar={(0,c) for r,c in bars[0] if r==0}; bbar={(H-1,c) for r,c in bars[1] if r==H-1}
    # singles: color != bg and not in either bar
    singles=[(r,c) for r in range(H) for c in range(W) if I[r][c]!=bg and (r,c) not in b1 and (r,c) not in b2]
    scolor=singles[0][1]
