    tstart=min(c for _,c in b1); tend=max(c for _,c in b1)
    ostart=min(c for _,c in b2); oend=max(c for _,c in b2)
    for (r,c) in singles:
        # own stripe: from top bar down to single
        for rr in range(tstart_r:=0, r):
            O[rr][c]=scolor
        O[r][c]=4
        # mapped stripe: offset from top span; skip if middle of a run of adjacent singles
        o=c-tstart
        if o<0 or o>tend-tstart: continue
        # run membership
        L=(c-1 in [x[1] for x in singles]); R=(c+1 in [x[1] for x in singles])
        if L and R: continue
        cc=ostart+o
        if ostart<=cc<=oend:
            for rr in range(H):
                if (rr,cc) in bbar: continue
                O[rr][cc]=scolor
    return O
